import {validate} from './room-model.mjs';
import {wallSegments,wallPoint,projectToWall,fitRect} from './room-geometry.mjs';
export function reshapeRoom(p,shape){const next=structuredClone(p),old=wallSegments(p);next.shape=shape;const walls=wallSegments(next);next.walls=walls.map(s=>{const mid=[(s.a[0]+s.b[0])/2,(s.a[1]+s.b[1])/2],matches=old.filter(v=>v.normal[0]*s.normal[0]+v.normal[1]*s.normal[1]>.99).sort((a,b)=>projectToWall(a,...mid).distance-projectToWall(b,...mid).distance);return {...p.walls[(matches[0]||old[0]).index]};});next.furniture=next.furniture.map(f=>fitRect(next,f));next.openings=[];
 for(const o of p.openings){const center=wallPoint(p,o.wall,o.offset+o.width/2),normal=old[o.wall].normal,candidates=walls.filter(s=>s.length>=o.width&&s.normal[0]*normal[0]+s.normal[1]*normal[1]>.99).sort((a,b)=>projectToWall(a,...center).distance-projectToWall(b,...center).distance);let placed=false;
  for(const s of candidates){const preferred=Math.max(0,Math.min(s.length-o.width,projectToWall(s,...center).t-o.width/2));const offsets=[preferred,0,s.length-o.width,...next.openings.filter(b=>b.wall===s.index).flatMap(b=>[b.offset-o.width,b.offset+b.width])].filter(n=>n>=0&&n+o.width<=s.length+1e-8).sort((a,b)=>Math.abs(a-preferred)-Math.abs(b-preferred));for(const offset of offsets){const item={...o,wall:s.index,offset};next.openings.push(item);try{validate(next);placed=true;break;}catch{next.openings.pop();}}if(placed)break;}
  if(!placed)throw Error('Не удалось сохранить все окна и двери в новой форме. Уменьшите вырез или размеры проёмов.');
 }return validate(next);}
